    private val labels: ByteArray by lazy { decodeLabels() }

    fun displayName(argb: Int): String {
        val rgb = argb and 0x00FFFFFF
        val sampledName = exactName(rgb) ?: interpolatedName(rgb)
        return if (sampledName.endsWith("色")) sampledName else "${sampledName}色"
    }

    private fun exactName(rgb: Int): String? = when (rgb) {
        0x038387 -> "深青"
        0x7DE8EA -> "浅绿"
        0x1E88E5 -> "蓝色"
        0x90CAF9 -> "浅蓝色"
        0xE53935 -> "红色"
        0xFF9E9E -> "玫瑰红"
        0x43A047 -> "绿色"
        0xAEE5B3 -> "浅绿"
        0xFFA000 -> "橙色"
        0xFFE08A -> "浅黄色"
        0x212121 -> "深灰色"
        0xECEFF1 -> "冰蓝"
        else -> null
    }

    private fun interpolatedName(rgb: Int): String {
        val red = channelPosition((rgb ushr 16) and 0xFF)
        val green = channelPosition((rgb ushr 8) and 0xFF)
        val blue = channelPosition(rgb and 0xFF)
        val scores = FloatArray(names.size)
        for (redUpper in 0..1) {
            val redIndex = if (redUpper == 1) red.upper else red.lower
            val redWeight = if (redUpper == 1) red.fraction else 1f - red.fraction
            for (greenUpper in 0..1) {
                val greenIndex = if (greenUpper == 1) green.upper else green.lower
                val greenWeight = if (greenUpper == 1) green.fraction else 1f - green.fraction
                for (blueUpper in 0..1) {
                    val blueIndex = if (blueUpper == 1) blue.upper else blue.lower
                    val blueWeight = if (blueUpper == 1) blue.fraction else 1f - blue.fraction
                    val tableIndex = (redIndex * GRID_SIZE + greenIndex) * GRID_SIZE + blueIndex
                    val labelIndex = labels[tableIndex].toInt() and 0xFF
                    scores[labelIndex] += redWeight * greenWeight * blueWeight
                }
            }
        }
        var bestIndex = 0
        for (index in 1 until scores.size) {
            if (scores[index] > scores[bestIndex]) bestIndex = index
        }
        return names[bestIndex]
    }

    private fun channelPosition(channel: Int): ChannelPosition {
        val lastRegularValue = 252
        if (channel >= lastRegularValue) {
            return ChannelPosition(
                lower = GRID_SIZE - 2,
                upper = GRID_SIZE - 1,
                fraction = (channel - lastRegularValue) / 3f
            )
        }
        val lower = channel / STEP
        return ChannelPosition(lower, lower + 1, (channel - lower * STEP) / STEP.toFloat())
    }

    private fun decodeLabels(): ByteArray {
        val runs = Base64.getDecoder().decode(encodedRuns)
        check(runs.size % 2 == 0)
        val decoded = ByteArray(SAMPLE_COUNT)
        var outputIndex = 0
        var runIndex = 0
        while (runIndex < runs.size) {
            val label = runs[runIndex]
            val count = runs[runIndex + 1].toInt() and 0xFF
            check(outputIndex + count <= decoded.size)
            decoded.fill(label, outputIndex, outputIndex + count)
            outputIndex += count
            runIndex += 2
        }
        check(outputIndex == decoded.size)
        return decoded
    }

    private data class ChannelPosition(
        val lower: Int,
        val upper: Int,
        val fraction: Float
    )
}
